#include "jvm_boot.hpp"

#include <android/log.h>
#include <dlfcn.h>
#include <jni.h>

#include "overlay_dex.h"  // generated by module/build.sh: kOverlayDex[], kOverlayDexLen

#define LOG(...) __android_log_print(ANDROID_LOG_INFO, "RYEENZYXNZ", __VA_ARGS__)

namespace rz {
namespace {

using GetVMsFn = jint (*)(JavaVM**, jsize, jsize*);

GetVMsFn findGetVMs() {
    if (void* s = dlsym(RTLD_DEFAULT, "JNI_GetCreatedJavaVMs")) return reinterpret_cast<GetVMsFn>(s);
    for (const char* lib : {"libnativehelper.so", "libart.so", "libandroid_runtime.so"}) {
        if (void* h = dlopen(lib, RTLD_NOW)) {
            if (void* s = dlsym(h, "JNI_GetCreatedJavaVMs")) return reinterpret_cast<GetVMsFn>(s);
        }
    }
    return nullptr;
}

// NDK declares AttachCurrentThread(JNIEnv**, void*); the JDK header uses (void**, void*). Accept both.
template <typename VM, typename Env>
auto attachThread(VM* vm, Env** env, int) -> decltype(vm->AttachCurrentThread(env, nullptr)) {
    return vm->AttachCurrentThread(env, nullptr);
}
template <typename VM, typename Env>
jint attachThread(VM* vm, Env** env, long) {
    return vm->AttachCurrentThread(reinterpret_cast<void**>(env), nullptr);
}

std::string fail(JNIEnv* env, const char* why) {
    if (env && env->ExceptionCheck()) {
        env->ExceptionDescribe();
        env->ExceptionClear();
    }
    LOG("overlay boot failed: %s", why);
    return why;
}

}  // namespace

std::string bootOverlay(const std::string& filesDir) {
    GetVMsFn getVMs = findGetVMs();
    if (!getVMs) return "no-JNI_GetCreatedJavaVMs";
    JavaVM* vm = nullptr;
    jsize n = 0;
    if (getVMs(&vm, 1, &n) != JNI_OK || n < 1 || !vm) return "no-java-vm";

    JNIEnv* env = nullptr;
    bool attached = false;
    if (vm->GetEnv(reinterpret_cast<void**>(&env), JNI_VERSION_1_6) != JNI_OK) {
        if (attachThread(vm, &env, 0) != JNI_OK || !env) return "attach-failed";
        attached = true;
    }

    std::string err;
    do {
        jclass clClass = env->FindClass("java/lang/ClassLoader");
        jmethodID sysLoader = clClass ? env->GetStaticMethodID(clClass, "getSystemClassLoader", "()Ljava/lang/ClassLoader;") : nullptr;
        jobject parent = sysLoader ? env->CallStaticObjectMethod(clClass, sysLoader) : nullptr;
        if (!parent) { err = fail(env, "no-system-classloader"); break; }

        jobject buf = env->NewDirectByteBuffer(const_cast<unsigned char*>(kOverlayDex), static_cast<jlong>(kOverlayDexLen));
        jclass imClass = env->FindClass("dalvik/system/InMemoryDexClassLoader");
        if (!buf || !imClass) { err = fail(env, "no-InMemoryDexClassLoader"); break; }
        jmethodID ctor = env->GetMethodID(imClass, "<init>", "(Ljava/nio/ByteBuffer;Ljava/lang/ClassLoader;)V");
        jobject loader = ctor ? env->NewObject(imClass, ctor, buf, parent) : nullptr;
        if (!loader) { err = fail(env, "dex-load-failed"); break; }

        jmethodID loadClass = env->GetMethodID(clClass, "loadClass", "(Ljava/lang/String;)Ljava/lang/Class;");
        jstring cname = env->NewStringUTF("com.ryeenzyxnz.overlay.RzBoot");
        jobject boot = loadClass ? env->CallObjectMethod(loader, loadClass, cname) : nullptr;
        if (!boot) { err = fail(env, "RzBoot-not-found"); break; }

        jmethodID start = env->GetStaticMethodID(static_cast<jclass>(boot), "start", "(Ljava/lang/String;)V");
        if (!start) { err = fail(env, "RzBoot.start-missing"); break; }
        jstring dir = env->NewStringUTF(filesDir.c_str());
        env->CallStaticVoidMethod(static_cast<jclass>(boot), start, dir);
        if (env->ExceptionCheck()) { err = fail(env, "RzBoot.start-threw"); break; }
        LOG("overlay started");
    } while (false);

    if (attached) vm->DetachCurrentThread();
    return err;
}

}  // namespace rz
